import React, { useState, useEffect } from 'react';
import { Card, Button, Alert, api } from '../App';

export default function MarkingPage() {
  const [parties,   setParties]   = useState([]);
  const [saleNos,   setSaleNos]   = useState([]);
  const [grades,    setGrades]    = useState([]);
  const [brokers,   setBrokers]   = useState([]);

  // Multi-select filters
  const [selParties,  setSelParties]  = useState([]);   // [{id,name,code}]
  const [saleNo,      setSaleNo]      = useState('');
  const [selGrades,   setSelGrades]   = useState([]);
  const [selBrokers,  setSelBrokers]  = useState([]);
  const [priceMin,    setPriceMin]    = useState('');
  const [priceMax,    setPriceMax]    = useState('');
  const [dateFrom,    setDateFrom]    = useState('');
  const [dateTo,      setDateTo]      = useState('');
  const [bagsMin,     setBagsMin]     = useState('');
  const [bagsMax,     setBagsMax]     = useState('');
  const [skipBlank,   setSkipBlank]   = useState(true);
  const [aiWeeks,     setAiWeeks]     = useState('2');

  // Preview state
  const [preview,  setPreview]  = useState([]);  // array of lots with party_alloc
  const [prices,   setPrices]   = useState({});  // catalogue_id -> price
  const [skipRows, setSkipRows] = useState({});  // catalogue_id -> bool
  // Extra manual party assignments per lot: { catalogue_id: { P6:{name,code}, ... } }
  const [extraParties, setExtraParties] = useState({});
  const [dupWarnings,  setDupWarnings]  = useState([]);

  const [loading,  setLoading]  = useState(false);
  const [saving,   setSaving]   = useState(false);
  const [alert,    setAlert]    = useState(null);
  const [showFilters, setShowFilters] = useState(true);

  useEffect(()=>{
    Promise.all([
      api.get('/parties').catch(()=>({data:[]})),
      api.get('/import/sale-numbers').catch(()=>({data:[]})),
      api.get('/marking/grades/list').catch(()=>({data:[]})),
      api.get('/marking/brokers/list').catch(()=>({data:[]}))
    ]).then(([p,s,g,b])=>{
      setParties(p.data);setSaleNos(s.data);setGrades(g.data);setBrokers(b.data);
    });
  },[]);

  const toggleParty = (p) => {
    setSelParties(prev=>prev.find(x=>x.id===p.id)?prev.filter(x=>x.id!==p.id):[...prev,p]);
  };
  const toggleGrade  = (g) => setSelGrades(prev=>prev.includes(g)?prev.filter(x=>x!==g):[...prev,g]);
  const toggleBroker = (b) => setSelBrokers(prev=>prev.includes(b)?prev.filter(x=>x!==b):[...prev,b]);

  const runPreview = async () => {
    if(!selParties.length||!saleNo){setAlert({msg:'Select at least one party and a sale number',type:'error'});return;}
    setLoading(true);setAlert(null);setDupWarnings([]);
    try {
      const r = await api.post('/marking/preview',{
        party_ids:  selParties.map(p=>p.id),
        sale_no:    saleNo,
        grades:     selGrades,
        price_min:  priceMin?parseFloat(priceMin):undefined,
        price_max:  priceMax?parseFloat(priceMax):undefined,
        brokers:    selBrokers,
        date_from:  dateFrom||undefined,
        date_to:    dateTo||undefined,
        bags_min:   bagsMin?parseInt(bagsMin):undefined,
        bags_max:   bagsMax?parseInt(bagsMax):undefined,
        skip_no_last_price: skipBlank,
      });
      setPreview(r.data);
      const init={};
      r.data.forEach(row=>{init[row.catalogue_id]=row.suggested_price?Number(row.suggested_price).toFixed(2):'';});
      setPrices(init);setSkipRows({});setExtraParties({});
      if(r.data.length===0)setAlert({msg:'No lots found. Check party garden mappings and grade settings.',type:'warning'});
    } catch(e){setAlert({msg:e.response?.data?.error||e.message,type:'error'});}
    finally{setLoading(false);}
  };

  const addExtraParty = (catalogueId, partyCode) => {
    const p = parties.find(x=>x.party_code===partyCode.toUpperCase().trim());
    if(!p){setAlert({msg:`Party code "${partyCode}" not found`,type:'error'});return;}
    // Check if already allocated
    const lot = preview.find(x=>x.catalogue_id===catalogueId);
    const existing = lot?Object.values(lot.party_alloc||{}).find(x=>x.party_code===p.party_code):null;
    const existingExtra = extraParties[catalogueId]?Object.values(extraParties[catalogueId]).find(x=>x.party_code===p.party_code):null;
    if(existing||existingExtra){
      setDupWarnings([`⚠️ ${p.party_name} (${p.party_code}) is already assigned to ${lot?.garden}/${lot?.grade}`]);
      return;
    }
    setExtraParties(prev=>{
      const curr = prev[catalogueId]||{};
      const nextIdx = Object.keys(curr).length + selParties.length + 1;
      return {...prev, [catalogueId]:{...curr,[`P${nextIdx}`]:{party_id:p.id,party_name:p.party_name,party_code:p.party_code,allocated:true}}};
    });
    setDupWarnings([]);
  };

  const save = async () => {
    const markings = preview.filter(r=>!skipRows[r.catalogue_id]).map(row=>{
      const alloc = {...(row.party_alloc||{}), ...(extraParties[row.catalogue_id]||{})};
      return {
        ...row,
        party_alloc: alloc,
        final_price: prices[row.catalogue_id]||row.suggested_price,
        price_min: priceMin||undefined,
        price_max: priceMax||undefined,
        status:'confirmed'
      };
    });
    if(!markings.length){setAlert({msg:'No markings to save',type:'warning'});return;}
    setSaving(true);
    try {
      const r=await api.post('/marking/save',{markings,sale_no:saleNo});
      setAlert({msg:`✅ ${r.data.saved} markings saved.${r.data.duplicates>0?` ${r.data.duplicates} duplicates skipped.`:''} Go to Labels to print.`,type:'success'});
      if(r.data.warnings?.length>0)setDupWarnings(r.data.warnings);
      setPreview([]);
    } catch(e){setAlert({msg:e.response?.data?.error||e.message,type:'error'});}
    finally{setSaving(false);}
  };

  const fmt = v=>v!==null&&v!==undefined?Number(v).toFixed(2):'—';
  const activeCount = preview.filter(r=>!skipRows[r.catalogue_id]).length;

  // Get all party column headers (P1..Pmax across all rows)
  const maxPartyIdx = Math.max(selParties.length, 1);

  const [addPartyInputs, setAddPartyInputs] = useState({}); // catalogueId -> input value

  return (
    <div>
      <h2 style={{marginBottom:4,color:'#1a3c5e'}}>✅ Create Markings</h2>
      <p style={{color:'#888',fontSize:13,marginBottom:20}}>Select multiple parties. Top N lots per grade are fetched based on grade sample settings in Mapping.</p>

      {alert&&<Alert msg={alert.msg} type={alert.type}/>}
      {dupWarnings.length>0&&(
        <div style={{background:'#fffbeb',border:'1px solid #fde68a',borderRadius:8,padding:'8px 14px',marginBottom:12,fontSize:12,color:'#92400e'}}>
          {dupWarnings.map((w,i)=><div key={i}>{w}</div>)}
        </div>
      )}

      {/* FILTER PANEL */}
      <Card style={{marginBottom:14}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:12}}>
          <h3 style={{fontSize:15}}>⚙️ Filters</h3>
          <button onClick={()=>setShowFilters(!showFilters)} style={{background:'none',border:'none',cursor:'pointer',color:'#888',fontSize:12}}>{showFilters?'▲ Hide':'▼ Show'}</button>
        </div>
        {showFilters&&<>
          {/* Parties (multi-select chips) */}
          <div style={{marginBottom:14}}>
            <div style={{fontSize:11,fontWeight:700,color:'#555',marginBottom:6,textTransform:'uppercase',letterSpacing:0.4}}>
              Parties * <span style={{fontWeight:400,color:'#888'}}>(select one or more)</span>
            </div>
            <div style={{display:'flex',gap:6,flexWrap:'wrap',maxHeight:120,overflowY:'auto',padding:'2px 0'}}>
              {parties.map(p=>{
                const sel=selParties.find(x=>x.id===p.id);
                return (
                  <div key={p.id} onClick={()=>toggleParty(p)}
                    style={{padding:'5px 12px',borderRadius:20,cursor:'pointer',fontSize:12,fontWeight:600,userSelect:'none',transition:'all 0.1s',
                      background:sel?'#1a3c5e':'#f0f4f8',color:sel?'#fff':'#555',
                      border:`1.5px solid ${sel?'#1a3c5e':'#e2e8f0'}`}}>
                    {sel?`✓ `:''}[{p.party_code}] {p.party_name}
                  </div>
                );
              })}
            </div>
            {selParties.length>0&&(
              <div style={{fontSize:11,color:'#1a7a4a',marginTop:4}}>
                Selected: {selParties.map(p=>`${p.party_name} (${p.party_code})`).join(' · ')}
              </div>
            )}
          </div>

          {/* Row: Sale, Price, Date */}
          <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr 1fr',gap:12,marginBottom:12}}>
            <div>
              <label style={{display:'block',fontSize:11,fontWeight:700,color:'#555',marginBottom:4,textTransform:'uppercase',letterSpacing:0.4}}>Sale Number *</label>
              <select value={saleNo} onChange={e=>setSaleNo(e.target.value)}
                style={{width:'100%',padding:'8px 10px',border:'1.5px solid #cbd5e0',borderRadius:6,fontSize:13}}>
                <option value="">Select sale…</option>
                {saleNos.map(s=><option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no}</option>)}
              </select>
            </div>
            <div>
              <label style={{display:'block',fontSize:11,fontWeight:700,color:'#555',marginBottom:4,textTransform:'uppercase',letterSpacing:0.4}}>Price Bracket (₹)</label>
              <div style={{display:'flex',gap:6}}>
                <input value={priceMin} onChange={e=>setPriceMin(e.target.value)} type="number" placeholder="Min"
                  style={{width:'50%',padding:'8px 8px',border:'1.5px solid #cbd5e0',borderRadius:6,fontSize:13}}/>
                <input value={priceMax} onChange={e=>setPriceMax(e.target.value)} type="number" placeholder="Max"
                  style={{width:'50%',padding:'8px 8px',border:'1.5px solid #cbd5e0',borderRadius:6,fontSize:13}}/>
              </div>
            </div>
            <div>
              <label style={{display:'block',fontSize:11,fontWeight:700,color:'#555',marginBottom:4,textTransform:'uppercase',letterSpacing:0.4}}>Date From</label>
              <input value={dateFrom} onChange={e=>setDateFrom(e.target.value)} type="date"
                style={{width:'100%',padding:'8px 10px',border:'1.5px solid #cbd5e0',borderRadius:6,fontSize:13}}/>
            </div>
            <div>
              <label style={{display:'block',fontSize:11,fontWeight:700,color:'#555',marginBottom:4,textTransform:'uppercase',letterSpacing:0.4}}>Date To</label>
              <input value={dateTo} onChange={e=>setDateTo(e.target.value)} type="date"
                style={{width:'100%',padding:'8px 10px',border:'1.5px solid #cbd5e0',borderRadius:6,fontSize:13}}/>
            </div>
          </div>

          {/* Row: Bags, Broker, Grade */}
          <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12,marginBottom:14}}>
            <div>
              <label style={{display:'block',fontSize:11,fontWeight:700,color:'#555',marginBottom:4,textTransform:'uppercase',letterSpacing:0.4}}>Bags (min–max)</label>
              <div style={{display:'flex',gap:6}}>
                <input value={bagsMin} onChange={e=>setBagsMin(e.target.value)} type="number" placeholder="Min"
                  style={{width:'50%',padding:'8px 8px',border:'1.5px solid #cbd5e0',borderRadius:6,fontSize:13}}/>
                <input value={bagsMax} onChange={e=>setBagsMax(e.target.value)} type="number" placeholder="Max"
                  style={{width:'50%',padding:'8px 8px',border:'1.5px solid #cbd5e0',borderRadius:6,fontSize:13}}/>
              </div>
            </div>
            <div>
              <label style={{display:'block',fontSize:11,fontWeight:700,color:'#555',marginBottom:4,textTransform:'uppercase',letterSpacing:0.4}}>Net Wt (min–max)</label>
              <div style={{display:'flex',gap:6}}>
                <input value={bagsMin} onChange={e=>setBagsMin(e.target.value)} type="number" placeholder="Min kg"
                  style={{width:'50%',padding:'8px 8px',border:'1.5px solid #cbd5e0',borderRadius:6,fontSize:13}}/>
                <input value={bagsMax} onChange={e=>setBagsMax(e.target.value)} type="number" placeholder="Max kg"
                  style={{width:'50%',padding:'8px 8px',border:'1.5px solid #cbd5e0',borderRadius:6,fontSize:13}}/>
              </div>
            </div>
          </div>

          {/* Broker multi-select */}
          {brokers.length>0&&(
            <div style={{marginBottom:12}}>
              <div style={{fontSize:11,fontWeight:700,color:'#555',marginBottom:6,textTransform:'uppercase',letterSpacing:0.4}}>Broker</div>
              <div style={{display:'flex',gap:6,flexWrap:'wrap'}}>
                {brokers.map(b=>(
                  <span key={b} onClick={()=>toggleBroker(b)}
                    style={{padding:'4px 12px',borderRadius:20,fontSize:12,fontWeight:600,cursor:'pointer',userSelect:'none',
                      background:selBrokers.includes(b)?'#1a3c5e':'#f0f4f8',
                      color:selBrokers.includes(b)?'#fff':'#555',
                      border:`1.5px solid ${selBrokers.includes(b)?'#1a3c5e':'#e2e8f0'}`}}>
                    {selBrokers.includes(b)?'✓ ':''}{b}
                  </span>
                ))}
              </div>
            </div>
          )}

          {/* Grade multi-select */}
          <div style={{marginBottom:14}}>
            <div style={{fontSize:11,fontWeight:700,color:'#555',marginBottom:6,textTransform:'uppercase',letterSpacing:0.4}}>Grade Filter</div>
            <div style={{display:'flex',gap:6,flexWrap:'wrap'}}>
              {grades.map(g=>(
                <span key={g} onClick={()=>toggleGrade(g)}
                  style={{padding:'4px 12px',borderRadius:20,fontSize:12,fontWeight:600,cursor:'pointer',userSelect:'none',
                    background:selGrades.includes(g)?'#1a7a4a':'#f0f4f8',
                    color:selGrades.includes(g)?'#fff':'#555',
                    border:`1.5px solid ${selGrades.includes(g)?'#1a7a4a':'#e2e8f0'}`}}>
                  {selGrades.includes(g)?'✓ ':''}{g}
                </span>
              ))}
              {selGrades.length>0&&<span onClick={()=>setSelGrades([])} style={{padding:'4px 12px',borderRadius:20,fontSize:12,cursor:'pointer',color:'#c0392b',border:'1.5px solid #c0392b'}}>✕ Clear</span>}
            </div>
          </div>

          <div style={{display:'flex',alignItems:'center',gap:20,flexWrap:'wrap',marginBottom:14}}>
            <label style={{display:'flex',alignItems:'center',gap:8,fontSize:13,cursor:'pointer'}}>
              <input type="checkbox" checked={skipBlank} onChange={e=>setSkipBlank(e.target.checked)}/>
              Skip lots where last sale price is blank
            </label>
            <div style={{display:'flex',alignItems:'center',gap:8,fontSize:13}}>
              <span style={{color:'#555',fontWeight:600}}>AI history:</span>
              <select value={aiWeeks} onChange={e=>setAiWeeks(e.target.value)}
                style={{padding:'5px 8px',border:'1.5px solid #e2e8f0',borderRadius:6,fontSize:13}}>
                <option value="2">Last 2 weeks</option>
                <option value="4">Last 4 weeks</option>
              </select>
            </div>
          </div>

          <Button onClick={runPreview} disabled={loading||!selParties.length||!saleNo} variant="primary">
            {loading?'⏳ Loading…':'🔍 Preview Lots'}
          </Button>
        </>}
      </Card>

      {/* PREVIEW TABLE */}
      {preview.length>0&&(
        <Card>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:12}}>
            <div>
              <h3 style={{fontSize:15}}>{preview.length} lots · {activeCount} active</h3>
              <div style={{fontSize:12,color:'#888',marginTop:2}}>
                Parties: {selParties.map((p,i)=><span key={p.id} style={{background:'#dbeafe',color:'#1e40af',padding:'1px 7px',borderRadius:99,fontSize:11,fontWeight:600,marginRight:4}}>P{i+1}: {p.party_code}</span>)}
              </div>
            </div>
            <div style={{display:'flex',gap:8}}>
              <Button size="sm" variant="outline" onClick={()=>setSkipRows({})}>Un-skip All</Button>
              <Button onClick={save} disabled={saving||activeCount===0} variant="success">
                {saving?'Saving…':`💾 Save ${activeCount} Markings`}
              </Button>
            </div>
          </div>

          <div style={{overflowX:'auto'}}>
            <table style={{width:'100%',borderCollapse:'collapse',fontSize:12}}>
              <thead>
                <tr style={{background:'#1a3c5e',color:'#fff'}}>
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap'}}>Skip</th>
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap'}}>Garden (Mark)</th>
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap'}}>Grade</th>
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap'}}>Bags</th>
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap'}}>Net Wt</th>
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap'}}>Min ₹</th>
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap'}}>Max ₹</th>
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap'}}>Broker</th>
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap'}}>Final Price ₹</th>
                  {selParties.map((_,i)=>(
                    <th key={i} style={{padding:'8px 8px',textAlign:'center',fontWeight:600,whiteSpace:'nowrap',background:'#234d78'}}>
                      P{i+1}
                    </th>
                  ))}
                  <th style={{padding:'8px 8px',textAlign:'left',fontWeight:600,whiteSpace:'nowrap',background:'#234d78'}}>+ Add Party</th>
                </tr>
              </thead>
              <tbody>
                {(() => {
                  let lastGrade = null;
                  return preview.map((row,i)=>{
                    const skip=!!skipRows[row.catalogue_id];
                    const gradeHeader = row.grade!==lastGrade;
                    lastGrade=row.grade;
                    return (
                      <React.Fragment key={row.catalogue_id}>
                        {gradeHeader&&(
                          <tr>
                            <td colSpan={9+selParties.length+1} style={{background:'#f0f4f8',padding:'6px 10px',fontWeight:700,fontSize:12,color:'#1a3c5e',borderBottom:'2px solid #e2e8f0'}}>
                              📊 Grade: {row.grade}
                            </td>
                          </tr>
                        )}
                        <tr style={{borderBottom:'1px solid #f0f4f8',background:skip?'#fff5f5':(i%2===0?'#fff':'#fafbfc'),opacity:skip?0.4:1}}>
                          <td style={{padding:'6px 8px'}}><input type="checkbox" checked={skip} onChange={()=>setSkipRows(s=>({...s,[row.catalogue_id]:!s[row.catalogue_id]}))}/></td>
                          <td style={{padding:'6px 8px',fontWeight:700,color:'#1a3c5e',maxWidth:160,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{row.garden}</td>
                          <td style={{padding:'6px 8px'}}><span style={{background:'#dbeafe',color:'#1e40af',padding:'2px 7px',borderRadius:99,fontSize:11,fontWeight:700}}>{row.grade}</span></td>
                          <td style={{padding:'6px 8px'}}>{row.bags||'—'}</td>
                          <td style={{padding:'6px 8px'}}>{row.net_wt||'—'}</td>
                          <td style={{padding:'6px 8px',color:'#1a7a4a',fontWeight:600}}>{row.min_deal_price?`₹${Number(row.min_deal_price).toFixed(0)}`:'—'}</td>
                          <td style={{padding:'6px 8px',color:'#c0392b',fontWeight:600}}>{row.max_deal_price?`₹${Number(row.max_deal_price).toFixed(0)}`:'—'}</td>
                          <td style={{padding:'6px 8px',color:'#888',fontSize:11}}>{row.broker||'—'}</td>
                          <td style={{padding:'6px 8px'}}>
                            <div style={{display:'flex',alignItems:'center',gap:3}}>
                              <span style={{fontSize:11,color:'#888'}}>₹</span>
                              <input type="number" value={prices[row.catalogue_id]||''} disabled={skip}
                                onChange={e=>setPrices(p=>({...p,[row.catalogue_id]:e.target.value}))}
                                style={{width:70,padding:'3px 6px',border:'1.5px solid #cbd5e0',borderRadius:5,fontSize:12,fontFamily:'monospace'}}/>
                            </div>
                          </td>
                          {selParties.map((p,idx)=>(
                            <td key={idx} style={{padding:'6px 8px',textAlign:'center'}}>
                              <span style={{background:'#dcfce7',color:'#166534',padding:'2px 8px',borderRadius:99,fontSize:11,fontWeight:700}}>{p.party_code}</span>
                            </td>
                          ))}
                          <td style={{padding:'6px 8px'}}>
                            <div style={{display:'flex',gap:4,alignItems:'center'}}>
                              <input
                                value={addPartyInputs[row.catalogue_id]||''}
                                onChange={e=>setAddPartyInputs(prev=>({...prev,[row.catalogue_id]:e.target.value}))}
                                placeholder="Code" maxLength={5}
                                style={{width:55,padding:'3px 6px',border:'1.5px solid #cbd5e0',borderRadius:5,fontSize:11,textTransform:'uppercase'}}
                              />
                              <button onClick={()=>{
                                addExtraParty(row.catalogue_id,addPartyInputs[row.catalogue_id]||'');
                                setAddPartyInputs(prev=>({...prev,[row.catalogue_id]:''}));
                              }} style={{padding:'3px 8px',background:'#1a3c5e',color:'#fff',border:'none',borderRadius:5,cursor:'pointer',fontSize:11}}>+</button>
                              {extraParties[row.catalogue_id]&&Object.values(extraParties[row.catalogue_id]).map((ep,ei)=>(
                                <span key={ei} style={{background:'#fef9c3',color:'#854d0e',padding:'2px 8px',borderRadius:99,fontSize:11,fontWeight:700}}>{ep.party_code}</span>
                              ))}
                            </div>
                          </td>
                        </tr>
                      </React.Fragment>
                    );
                  });
                })()}
              </tbody>
            </table>
          </div>

          <div style={{marginTop:12,padding:10,background:'#eff6ff',border:'1px solid #bfdbfe',borderRadius:6,fontSize:12,color:'#1e40af'}}>
            ℹ️ P1–P{selParties.length} are auto-assigned from selected parties. Use "+ Add Party" column to manually add extra parties by code for specific lots.
          </div>
        </Card>
      )}
    </div>
  );
}
